import { useMemo, useState } from "react";
import { useFetcher } from "react-router";
import { boundary } from "@shopify/shopify-app-react-router/server";
import { authenticate } from "../shopify.server";
import { generateTransferSheetsByProduct } from "../orderMetafieldApi.server";

export const loader = async ({ request }) => {
  // Sheets are generated by the action, not on page load — rendering them is
  // expensive and would re-run on every refresh.
  await authenticate.admin(request);
  return null;
};

/** Split the free-text field into a de-duped list of order IDs. */
function parseOrderIds(raw) {
  return [
    ...new Set(
      String(raw || "")
        .split(/[\s,]+/)
        .map((id) => id.trim())
        .filter(Boolean),
    ),
  ];
}

export const action = async ({ request }) => {
  const { session } = await authenticate.admin(request);
  const form = await request.formData();
  const orderIds = parseOrderIds(form.get("orderIds"));

  if (!orderIds.length) {
    return { ok: false, orders: [], error: "Enter at least one order ID." };
  }

  try {
    const res = await generateTransferSheetsByProduct({
      shop: session.shop,
      orderIds,
    });

    if (!res.ok) {
      const text = await res.text();
      return {
        ok: false,
        orders: [],
        error: `API returned ${res.status}: ${text.slice(0, 200)}`,
      };
    }

    const data = await res.json().catch(() => null);
    const orders = Array.isArray(data?.orders) ? data.orders : [];

    if (!orders.length) {
      return {
        ok: false,
        orders: [],
        error: data?.error || "The service returned no results for these orders.",
      };
    }

    // The API reports success: true even when every order failed, so the real
    // outcome has to come from the per-order entries.
    return { ok: true, orders, error: null };
  } catch (err) {
    console.error("[app.orders] transfer sheet generation failed:", err);
    return {
      ok: false,
      orders: [],
      error: err.message || "Failed to reach the transfer sheet service.",
    };
  }
};

