/** Same-origin proxy download so the browser saves the file instead of opening it. */
function downloadHref(sheet) {
  return sheet.pngFileName
    ? `/app/orders/download?file=${encodeURIComponent(sheet.pngFileName)}`
    : sheet.downloadUrl || null;
}

function sheetLabel(sheet) {
  const title = sheet.productTitle || "Transfer sheet";
  return sheet.partCount > 1
    ? `${title} (Sheet ${sheet.partIndex} of ${sheet.partCount})`
    : title;
}

function sheetSize(sheet) {
  const dims = sheet.sheetDimensions;
  return dims ? `${dims.widthIn}" × ${dims.heightIn}"` : "Size unavailable";
}

export default function OrdersPage() {
  const fetcher = useFetcher();
  const [orderIdInput, setOrderIdInput] = useState("");

  const isGenerating = fetcher.state !== "idle";
  const result = fetcher.data;
  const orders = useMemo(() => result?.orders || [], [result]);

  const parsedIds = useMemo(() => parseOrderIds(orderIdInput), [orderIdInput]);

  const summary = useMemo(() => {
    const ready = orders.filter((o) => o.success);
    return {
      ready: ready.length,
      failed: orders.length - ready.length,
      sheets: ready.reduce((n, o) => n + (o.sheets?.length || 0), 0),
    };
  }, [orders]);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!parsedIds.length) return;
    const fd = new FormData();
    fd.set("orderIds", parsedIds.join(","));
    fetcher.submit(fd, { method: "post" });
  };

  // Downloads are triggered one at a time; browsers drop simultaneous ones.
  const downloadAll = (sheets) => {
    sheets
      .map(downloadHref)
      .filter(Boolean)
      .forEach((href, i) => {
        setTimeout(() => {
          const a = document.createElement("a");
          a.href = href;
          a.download = "";
          document.body.appendChild(a);
          a.click();
          a.remove();
        }, i * 400);
      });
  };

  return (
    <s-page heading="Transfer sheets">
      <s-section>
        <s-box padding="base">
          <style>{PAGE_CSS}</style>
          <div className="ots-wrap">
            <div className="ots-card">
              <div className="ots-card-header">
                <div>
                  <h3 className="ots-card-title">Generate transfer sheets</h3>
                  <div className="ots-card-sub">
                    Designs are grouped by product and packed onto 22.5&quot;
                    wide sheets at 300 DPI.
                  </div>
                </div>
              </div>

              <form onSubmit={handleSubmit}>
                <label className="ots-label" htmlFor="order-ids">
                  Order ID
                </label>
                <input
                  id="order-ids"
                  type="text"
                  value={orderIdInput}
                  onChange={(e) => setOrderIdInput(e.target.value)}
                  placeholder="e.g. 6103847291"
                  className="ots-input"
                  disabled={isGenerating}
                  autoComplete="off"
                />
                <div className="ots-hint">
                  Numeric order ID from the Shopify admin URL. Separate multiple
                  IDs with a comma or space
                  {parsedIds.length > 1 ? ` — ${parsedIds.length} detected` : ""}
                  .
                </div>

                <div className="ots-actions">
                  <button
                    type="submit"
                    className="ots-btn ots-btn-primary"
                    disabled={isGenerating || !parsedIds.length}
                  >
                    {isGenerating && <span className="ots-spinner" />}
                    {isGenerating ? "Generating…" : "Generate sheets"}
                  </button>
                  {orderIdInput && !isGenerating && (
                    <button
                      type="button"
                      className="ots-btn ots-btn-secondary"
                      onClick={() => setOrderIdInput("")}
                    >
                      Clear
                    </button>
                  )}
                </div>
              </form>
            </div>

            {isGenerating && (
              <div className="ots-banner ots-banner-info">
                <span style={{ fontWeight: 700 }}>Working</span>
                <span>
                  Rendering sheets for {parsedIds.length}{" "}
                  {parsedIds.length === 1 ? "order" : "orders"}. This can take
                  tens of seconds per order — keep this tab open.
                </span>
              </div>
            )}

            {result?.error && (
              <div className="ots-banner ots-banner-error">
                <span style={{ fontWeight: 700 }}>Error</span>
                <span>{result.error}</span>
              </div>
            )}

            {!isGenerating && orders.length > 0 && (
              <>
                {summary.ready === 0 ? (
                  <div className="ots-banner ots-banner-warn">
                    <span style={{ fontWeight: 700 }}>No sheets</span>
                    <span>
                      None of the {orders.length}{" "}
                      {orders.length === 1 ? "order" : "orders"} produced a
                      transfer sheet. See the details below.
                    </span>
                  </div>
                ) : (
                  <div className="ots-banner ots-banner-info">
                    <span style={{ fontWeight: 700 }}>Ready</span>
                    <span>
                      {summary.sheets}{" "}
                      {summary.sheets === 1 ? "sheet" : "sheets"} across{" "}
                      {summary.ready}{" "}
                      {summary.ready === 1 ? "order" : "orders"}
                      {summary.failed > 0
                        ? ` — ${summary.failed} could not be generated`
                        : ""}
                      .
                    </span>
                  </div>
                )}

                {orders.map((order) => {
                  const sheets = order.sheets || [];
                  return (
                    <div className="ots-order" key={order.orderId}>
                      <div className="ots-order-head">
                        <div>
                          <div className="ots-order-name">
                            {order.orderName || `Order ${order.orderId}`}
                          </div>
                          <div className="ots-order-meta">
                            ID {order.orderId}
                            {order.success
                              ? ` · ${order.totalDesigns} design${
                                  order.totalDesigns === 1 ? "" : "s"
                                } · ${sheets.length} sheet${
                                  sheets.length === 1 ? "" : "s"
                                }`
                              : ""}
                          </div>
                        </div>
                        {order.success ? (
                          <div className="ots-sheet-actions">
                            <span className="ots-badge">Ready</span>
                            {sheets.length > 1 && (
                              <button
                                type="button"
                                className="ots-btn ots-btn-small ots-btn-secondary"
                                onClick={() => downloadAll(sheets)}
                              >
                                Download all ({sheets.length})
                              </button>
                            )}
                          </div>
                        ) : (
                          <span
                            className={`ots-badge ${
                              order.skipped
                                ? "ots-badge-neutral"
                                : "ots-badge-warn"
                            }`}
                          >
                            {order.skipped ? "Skipped" : "Failed"}
                          </span>
                        )}
                      </div>

                      <div className="ots-order-body">
                        {!order.success && (
                          <p style={{ color: "#6d7175", fontSize: "13px" }}>
                            {order.message ||
                              (typeof order.error === "string"
                                ? order.error
                                : JSON.stringify(order.error)) ||
                              "No sheets were generated for this order."}
                          </p>
                        )}

                        {sheets.map((sheet) => {
                          const href = downloadHref(sheet);
                          return (
                            <div
                              className="ots-sheet"
                              key={sheet.pngFileName || `${sheet.productId}-${sheet.partIndex}`}
                            >
                              <div className="ots-sheet-info">
                                <div className="ots-sheet-title">
                                  {sheetLabel(sheet)}
                                </div>
                                <div className="ots-sheet-meta">
                                  {sheetSize(sheet)} · {sheet.totalDesigns}{" "}
                                  design{sheet.totalDesigns === 1 ? "" : "s"} ·
                                  Pre-cut: {sheet.preCut || "No"}
                                </div>
                                <div className="ots-sheet-meta">
                                  Product <span className="ots-mono">{sheet.productId}</span>
                                </div>

                                {sheet.designBreakdown?.length > 0 && (
                                  <table className="ots-breakdown">
                                    <thead>
                                      <tr>
                                        <th>Dimension</th>
                                        <th>Pre-cut</th>
                                      </tr>
                                    </thead>
                                    <tbody>
                                      {sheet.designBreakdown.map((item, i) => (
                                        <tr key={`${item.dimension}-${i}`}>
                                          <td>
                                            {item.dimension}
                                            {item.count > 1
                                              ? ` (×${item.count})`
                                              : ""}
                                          </td>
                                          <td>{item.preCut}</td>
                                        </tr>
                                      ))}
                                    </tbody>
                                  </table>
                                )}
                              </div>

                              <div className="ots-sheet-actions">
                                {href ? (
                                  <a
                                    href={href}
                                    download
                                    className="ots-btn ots-btn-small ots-btn-primary"
                                  >
                                    Download
                                  </a>
                                ) : (
                                  <span className="ots-badge ots-badge-warn">
                                    Unavailable
                                  </span>
                                )}
                                {sheet.downloadUrl && (
                                  <a
                                    href={sheet.downloadUrl}
                                    target="_blank"
                                    rel="noreferrer"
                                    className="ots-btn ots-btn-small ots-btn-secondary"
                                  >
                                    Preview
                                  </a>
                                )}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  );
                })}
              </>
            )}

            {!isGenerating && !result && (
              <div className="ots-empty">
                <div className="ots-empty-title">No sheets generated yet</div>
                <div>
                  Enter an order ID above to build its transfer sheets and
                  download them.
                </div>
              </div>
            )}
          </div>
        </s-box>
      </s-section>

      <s-section slot="aside" heading="About">
        <s-paragraph>
          Enter an <strong>Order ID</strong> to generate print-ready transfer
          sheets. Only line items carrying a <strong>CustomImage</strong>{" "}
          property are included — orders without one are skipped.
        </s-paragraph>
        <s-paragraph>
          Sheets are grouped per product and split into parts when a sheet would
          run past 300&quot; in length. Generating does not send an email.
        </s-paragraph>
      </s-section>
    </s-page>
  );
}

export const headers = (headersArgs) => {
  return boundary.headers(headersArgs);
};
